TypeScript example:
import { SDKClient } from '@redwood/sdk'
import { AdaptiveBatcher, StreamReader } from '@redwood/sdk/helpers'
const client = new SDKClient()
const batcher = new AdaptiveBatcher({ targetLatencyMs: 120, maxChunk: 256 })
const reader = new StreamReader(client.embeddings.batch, batcher)
for await (const r of reader.read(items)) {
  handle(r)
}

Go example:
client := sdk.NewClient()
chunker := helpers.NewAdaptiveChunker(120, 256)
iter := helpers.NewStreamIterator(client.Embeddings.Batch, chunker)
for iter.Next() {
  res := iter.Value()
  handle(res)
}
if err := iter.Err(); err != nil {
  // handle error
}
